/**
 * @summary Listar eventos consolidados (M365, dispositivos e externos)
 */
export const getListSecurityCenterEventsUrl = (
  params?: ListSecurityCenterEventsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/security-center/events?${stringifiedParams}`
    : `/api/security-center/events`;
};

